 public static String xml(String s){if(s==null)return "";StringBuilder b=new StringBuilder();for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='&')b.append("&amp;");else if(c=='<')b.append("&lt;");else if(c=='>')b.append("&gt;");else if(c=='\"')b.append("&quot;");else if(c=='\'')b.append("&apos;");else if(c=='\n'||c=='\t'||c=='\r'||c>=32&&c!=0xfffe&&c!=0xffff){if(Character.isHighSurrogate(c)){if(i+1<s.length()&&Character.isLowSurrogate(s.charAt(i+1)))b.append(c).append(s.charAt(++i));}else if(!Character.isLowSurrogate(c))b.append(c);}}return b.toString();}
 private static void put(Map<String,String> p,String n,String s){p.put(n,HEAD+s);}
