  String range="A1:"+column(columns.size()-1)+(rows.size()+1);StringBuilder sheet=new StringBuilder("<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><dimension ref=\""+range+"\"/><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight=\"24\"/><cols><col min=\"1\" max=\""+columns.size()+"\" width=\"24\" customWidth=\"1\"/></cols><sheetData><row r=\"1\" ht=\"32\" customHeight=\"1\">");
  for(int c=0;c<columns.size();c++)sheet.append(stringCell(column(c)+"1",1,columns.get(c)));sheet.append("</row>");
  for(int r=0;r<rows.size();r++){sheet.append("<row r=\"").append(r+2).append("\">");for(int c=0;c<columns.size();c++){Object v=rows.get(r).get(c);String ref=column(c)+(r+2);int style=r%2==0?2:0;if(v instanceof Number&&Double.isFinite(((Number)v).doubleValue()))sheet.append("<c r=\"").append(ref).append("\" s=\"").append(style).append("\"><v>").append(v).append("</v></c>");else sheet.append(stringCell(ref,style,v==null?"":String.valueOf(v)));}sheet.append("</row>");}
  sheet.append("</sheetData><autoFilter ref=\"").append(range).append("\"/><pageMargins left=\"0.3\" right=\"0.3\" top=\"0.5\" bottom=\"0.5\" header=\"0.2\" footer=\"0.2\"/></worksheet>");put(p,"xl/worksheets/sheet1.xml",sheet.toString());return zip(p);
