  put(p,"ppt/_rels/presentation.xml.rels",relationships.append("</Relationships>").toString());String clr="<p:clrMap bg1=\"lt1\" tx1=\"dk1\" bg2=\"lt2\" tx2=\"dk2\" accent1=\"accent1\" accent2=\"accent2\" accent3=\"accent3\" accent4=\"accent4\" accent5=\"accent5\" accent6=\"accent6\" hlink=\"hlink\" folHlink=\"folHlink\"/>";
  put(p,"ppt/slideMasters/slideMaster1.xml",root("sldMaster")+"<p:cSld name=\"AI Work Dark\"><p:spTree>"+group()+"</p:spTree></p:cSld>"+clr+"<p:sldLayoutIdLst><p:sldLayoutId id=\"2147483649\" r:id=\"rId1\"/></p:sldLayoutIdLst><p:txStyles><p:titleStyle/><p:bodyStyle/><p:otherStyle/></p:txStyles></p:sldMaster>");
